python3 - <<'PY'
from pathlib import Path

patch = Path('/tmp/theme.patch').read_text()
sections = patch.split('*** Update File: ')
for section in sections[1:]:
    path = section.splitlines()[0].split(' ', 1)[0]
    lines = section.splitlines()
    header = lines.index('@@')
    changes = lines[header:]
    target = Path(path)
    original = target.read_text().splitlines()
    result = []
    index = 0
    for line in changes[1:]:
        if line.startswith('+'):
            result.append(line[1:])
        elif line.startswith('-'):
            index += 1
        elif line.startswith(' '):
            result.append(line[1:])
            index += 1
    target.write_text('\\n'.join(result) + '\\n')
